file.content:
package cli

// AlreadyPrintedError marks a failure whose user-facing explanation the command
// has already written to the terminal. The entrypoint — the only component that
// prints an error — recognises the mark and prints nothing further, so a
// friendly, formatted diagnostic is never followed by a raw restatement of the
// same failure.
//
// The wrapped cause stays reachable through errors.As and errors.Is: marking an
// error as printed is a statement about output, not a decision to discard what
// went wrong.
type AlreadyPrintedError struct {
	Err error
}

// Error returns the wrapped cause's message. The entrypoint does not print it,
// but tests, logs and errors.Is comparisons still need it to be truthful.
func (e *AlreadyPrintedError) Error() string {
	return e.Err.Error()
}

// Unwrap exposes the cause so callers can inspect it.
func (e *AlreadyPrintedError) Unwrap() error {
	return e.Err
}

// AlreadyPrinted reports that the user-facing message has already been written.
func (e *AlreadyPrintedError) AlreadyPrinted() bool {
	return true
}

// NewAlreadyPrintedError marks err as already explained to the user. Call it
// only after writing that explanation; returning an unmarked error the command
// also printed is what produces duplicate output.
func NewAlreadyPrintedError(err error) *AlreadyPrintedError {
	return &AlreadyPrintedError{Err: err}
}

// Package logging provides structured logging for the Entire CLI using slog.
//
// Usage:
//
//	// Initialize logger for a session (typically at session start)
//	if err := logging.Init(sessionID); err != nil {
//	    // handle error
//	}
//	defer logging.Close()
//
//	// Add context values
//	ctx = logging.WithComponent(ctx, "hooks")
//	ctx = logging.WithAgent(ctx, agentName)
//
//	// Log with context - component/agent extracted automatically
//	logging.Info(ctx, "hook invoked",
//	    slog.String("hook", hookName),
//	    slog.String("branch", branch),
//	)
package logging

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/validation"
)

// LogLevelEnvVar is the environment variable that controls log level.
const LogLevelEnvVar = "ENTIRE_LOG_LEVEL"

// LogsDir is the directory where log files are stored (relative to repo root).
const LogsDir = ".entire/logs"

var (
	// logger is the package-level logger instance
	logger *slog.Logger

	// logFile holds the current log file handle for cleanup
	logFile *os.File

	// logBufWriter wraps logFile with buffered I/O for performance
	logBufWriter *bufio.Writer

	// currentSessionID stores the session ID from Init() to include in all logs
	currentSessionID string

	// mu protects logger, logFile, logBufWriter, and currentSessionID
	mu sync.RWMutex

	// logLevelGetter is an optional callback to get log level from settings.
	// Set by SetLogLevelGetter before Init is called.
	logLevelGetter func() string
)

// SetLogLevelGetter sets a callback function to get the log level from settings.
// This allows the logging package to read settings without a circular dependency.
// The callback is only used if ENTIRE_LOG_LEVEL env var is not set.
func SetLogLevelGetter(getter func() string) {
	mu.Lock()
	defer mu.Unlock()
	logLevelGetter = getter
}

// Init initializes the logger for a session, writing JSON logs to
// .entire/logs/entire.log.
//
// If sessionID is non-empty, it is stored as an slog attribute on every log line for filtering.
// If the log file cannot be created, falls back to stderr.
// Log level is controlled by ENTIRE_LOG_LEVEL environment variable.
func Init(ctx context.Context, sessionID string) error {
	// Validate session ID if provided (used only for the slog attribute, not the filename)
	if sessionID != "" {
		if err := validation.ValidateSessionID(sessionID); err != nil {
			return fmt.Errorf("invalid session ID for logging: %w", err)
		}
	}

	mu.Lock()
	defer mu.Unlock()

	// Close any existing log file (flush buffer first)
	if logBufWriter != nil {
		_ = logBufWriter.Flush()
		logBufWriter = nil
	}
	if logFile != nil {
		_ = logFile.Close()
		logFile = nil
	}

	// Get log level from environment first, then settings
	levelStr := os.Getenv(LogLevelEnvVar)
	if levelStr == "" && logLevelGetter != nil {
		levelStr = logLevelGetter()
	}
	level := parseLogLevel(levelStr)

	// Warn if invalid level was provided
	if levelStr != "" && !isValidLogLevel(levelStr) {
		fmt.Fprintf(os.Stderr, "[entire] Warning: invalid log level %q, defaulting to INFO\n", levelStr)
	}

	// Determine log file path
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		// Fall back to current directory
		repoRoot = "."
	}

	logsPath := filepath.Join(repoRoot, LogsDir)
	if err := os.MkdirAll(logsPath, 0o750); err != nil {
		// Fall back to stderr
		logger = createLogger(os.Stderr, level)
		return nil
	}

	logFilePath := filepath.Join(logsPath, "entire.log")
	f, err := os.OpenFile(logFilePath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600) //nolint:gosec // fixed filename, not user-controlled
	if err != nil {
		// Fall back to stderr
		logger = createLogger(os.Stderr, level)
		return nil
	}

	logFile = f
	logBufWriter = bufio.NewWriterSize(f, 8192) // 8KB buffer for batched writes
	logger = createLogger(logBufWriter, level)
	currentSessionID = sessionID

	return nil
}

// Close closes the log file if one is open.
// Flushes any buffered data before closing.
// Safe to call multiple times.
func Close() {
	mu.Lock()
	defer mu.Unlock()

	if logBufWriter != nil {
		_ = logBufWriter.Flush()
		logBufWriter = nil
	}
	if logFile != nil {
		_ = logFile.Close()
		logFile = nil
	}
	currentSessionID = ""
}

// resetLogger resets the logger to nil (for testing).
func resetLogger() {
	mu.Lock()
	defer mu.Unlock()
	logger = nil
	currentSessionID = ""
	if logBufWriter != nil {
		_ = logBufWriter.Flush()
		logBufWriter = nil
	}
	if logFile != nil {
		_ = logFile.Close()
		logFile = nil
	}
}

// createLogger creates a JSON logger writing to the given writer at the specified level.
func createLogger(w io.Writer, level slog.Level) *slog.Logger {
	opts := &slog.HandlerOptions{
		Level: level,
	}
	handler := slog.NewJSONHandler(w, opts)
	return slog.New(handler)
}

// parseLogLevel parses a log level string to slog.Level.
// Returns slog.LevelInfo for empty or invalid values.
func parseLogLevel(s string) slog.Level {
	switch strings.ToUpper(strings.TrimSpace(s)) {
	case "DEBUG":
		return slog.LevelDebug
	case "INFO":
		return slog.LevelInfo
	case "WARN", "WARNING":
		return slog.LevelWarn
	case "ERROR":
		return slog.LevelError
	default:
		return slog.LevelInfo
	}
}

// isValidLogLevel checks if the given string is a valid log level.
func isValidLogLevel(s string) bool {
	switch strings.ToUpper(strings.TrimSpace(s)) {
	case "DEBUG", "INFO", "WARN", "WARNING", "ERROR", "":
		return true
	default:
		return false
	}
}

// Debug logs at DEBUG level with context values automatically extracted.
func Debug(ctx context.Context, msg string, attrs ...any) {
	log(ctx, slog.LevelDebug, msg, attrs...)
}

// Info logs at INFO level with context values automatically extracted.
func Info(ctx context.Context, msg string, attrs ...any) {
	log(ctx, slog.LevelInfo, msg, attrs...)
}

// Warn logs at WARN level with context values automatically extracted.
func Warn(ctx context.Context, msg string, attrs ...any) {
	log(ctx, slog.LevelWarn, msg, attrs...)
}

// Error logs at ERROR level with context values automatically extracted.
func Error(ctx context.Context, msg string, attrs ...any) {
	log(ctx, slog.LevelError, msg, attrs...)
}

// log is the internal logging function that extracts context values and logs.
//
// The read lock is held across l.Log so Init/Close cannot close logBufWriter
// mid-write; do not shrink the lock scope to a snapshot pattern.
func log(ctx context.Context, level slog.Level, msg string, attrs ...any) {
	mu.RLock()
	defer mu.RUnlock()

	l := logger
	if l == nil {
		l = slog.Default()
	}
	globalSessionID := currentSessionID

	// Build attributes slice with session ID first (if set)
	var allAttrs []any

	// Add session ID from Init() if set (always first for consistency)
	if globalSessionID != "" {
		allAttrs = append(allAttrs, slog.String("session_id", globalSessionID))
	}

	// Extract context values
	contextAttrs := attrsFromContext(ctx)
	for _, a := range contextAttrs {
		allAttrs = append(allAttrs, a)
	}

	// Add caller-provided attributes
	allAttrs = append(allAttrs, attrs...)

	// Pass nil context to slog as we've already extracted context values as attributes.
	// slog handlers are expected to handle nil context gracefully.
	l.Log(nil, level, msg, allAttrs...) //nolint:staticcheck // nil context is intentional - we extract values as attributes
}

// attrsFromContext extracts logging attributes from a context.
func attrsFromContext(ctx context.Context) []slog.Attr {
	if ctx == nil {
		return nil
	}

	var attrs []slog.Attr

	if v := ctx.Value(componentKey); v != nil {
		if s, ok := v.(string); ok && s != "" {
			attrs = append(attrs, slog.String("component", s))
		}
	}
	if v := ctx.Value(agentKey); v != nil {
		if s, ok := v.(string); ok && s != "" {
			attrs = append(attrs, slog.String("agent", s))
		}
	}

	return attrs
}

package logging

import (
	"context"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// Context keys for logging values.
// Using private types to avoid key collisions.
type contextKey int

const (
	componentKey contextKey = iota
	agentKey
)

// WithComponent adds a component name to the context.
// Component names help identify the subsystem generating logs (e.g., "hooks", "strategy", "session").
func WithComponent(ctx context.Context, component string) context.Context {
	return context.WithValue(ctx, componentKey, component)
}

// WithAgent adds an agent name to the context.
// Agent names identify the AI agent generating activity (e.g., "claude-code", "cursor", "aider").
func WithAgent(ctx context.Context, agentName types.AgentName) context.Context {
	return context.WithValue(ctx, agentKey, string(agentName))
}

// Command harnaas manages a project's AI-harness assets as a declared,
// versioned dependency of the repository.
//
// This file owns the whole process contract: it is the only component that
// prints an error, the only one that chooses an exit code, and the only one
// that decides how a signal terminates the process. Commands return errors;
// what those errors look like on the terminal is decided here, once.
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/signal"
	"runtime"
	"strings"
	"syscall"
	"time"

	"github.com/harnaas/harnaas/cmd/harnaas/cli"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/versioninfo"
	"github.com/harnaas/harnaas/internal/procsignal"
	"github.com/spf13/cobra"
)

// The exit-code contract. Every status harnaas can produce is listed here, and
// a new one must not be introduced without a documented meaning.
//
//   - exitSuccess       the command completed and found nothing to report.
//   - exitFailure       any runtime failure: bad configuration, I/O, network.
//   - exitLintFindings  reserved: `lint` ran its checks to completion and
//     reported at least one error-severity finding.
//
// exitLintFindings exists so a CI job can tell "lint crashed" from "lint worked
// and your harness has drifted" — the distinction lint exists to make. It is
// reserved for that single meaning: no command other than `lint` may return it,
// and a lint run that fails partway through exits exitFailure like any other
// runtime failure. Nothing in this binary emits it yet; `lint` itself arrives
// with add-harnaas-lint, and reportError below never produces it.
//
// Termination by signal is not in this list because it is not an exit at all:
// see dieFromSignal, which re-raises the signal and only falls back to
// 128-plus-signal-number where re-raising is unsupported.
const (
	exitSuccess      = 0
	exitFailure      = 1
	exitLintFindings = 2
)

// forceQuitGrace is how long dieFromSignal waits for a re-raised signal to be
// delivered. Delivery ends the process well before this elapses; the wait only
// exists so a platform that silently drops the re-raise still reaches the
// fallback exit instead of hanging.
const forceQuitGrace = 500 * time.Millisecond

func main() {
	// Resolve version and commit before anything reads them — the root command
	// copies Version into its own field as it is built.
	versioninfo.Load()

	os.Exit(run())
}

// run executes the command tree and returns the process exit code. It exists
// as a separate function so the deferred cancel actually runs; main's os.Exit
// would skip it.
func run() int {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	watchSignals(cancel, os.Stderr)

	root := cli.NewRootCmd()

	// ExecuteContextC returns the deepest command cobra matched, which is the
	// one whose usage a positional-argument error should show.
	executed, err := root.ExecuteContextC(ctx)
	if err == nil {
		return exitSuccess
	}

	if sig := terminatingSignal(err); sig != nil {
		cancel()
		dieFromSignal(sig)
	}

	return reportError(root.ErrOrStderr(), root, executed, err)
}

// watchSignals installs the two-stage handler. The first signal cancels the
// root context so in-flight work unwinds cleanly and prints a notice; because
// signal.Notify has disabled Go's default "signal terminates the process"
// behaviour, a second read is what keeps a further Ctrl-C from being swallowed
// during a slow or stuck shutdown. The caught signal is recorded so the
// eventual termination re-raises that same signal rather than assuming an
// interrupt.
func watchSignals(cancel context.CancelFunc, notice io.Writer) {
	sigChan := make(chan os.Signal, 1)
	signals := []os.Signal{os.Interrupt}
	if runtime.GOOS != "windows" {
		signals = append(signals, syscall.SIGTERM)
	}
	signal.Notify(sigChan, signals...)

	go func() {
		sig := <-sigChan
		procsignal.Store(sig)
		fmt.Fprintln(notice, forceQuitNotice(sig))
		cancel()
		<-sigChan
		dieFromSignal(sig)
	}()
}

// forceQuitNotice is the advisory text for a first signal. It distinguishes an
// interrupt the user typed from a termination signal a supervisor sent, because
// the two want different explanations, and it leads with a blank line so the
// notice does not land on top of a half-written progress line.
func forceQuitNotice(sig os.Signal) string {
	if sig == os.Interrupt {
		return "\nInterrupting… press Ctrl-C again to force quit."
	}
	return "\nReceived termination signal, shutting down… signal again to force quit."
}

// terminatingSignal reports the signal that cancelled the root context, or nil
// if the cancellation was not signal-driven.
//
// The gate is deliberately on a signal having been recorded rather than on the
// error type alone: a context.Canceled that arose without a signal — an
// internally cancelled sub-context, say — is a genuine failure and must be
// reported as one, not dressed up as a user abort that would also wrongly break
// an enclosing shell loop.
func terminatingSignal(err error) os.Signal {
	if !errors.Is(err, context.Canceled) {
		return nil
	}
	return procsignal.Load()
}

// dieFromSignal terminates the process as if it had been killed by sig, rather
// than exiting normally.
//
// The distinction matters to an interactive shell: it aborts a
// `while true; do harnaas …; done` loop only when the child is *killed by*
// SIGINT. A plain exit with status 130 is an ordinary exit, so the loop keeps
// respawning harnaas and the user's Ctrl-C never escapes it. Re-raising the
// actual signal also keeps a SIGTERM shutdown reporting the conventional 143.
//
// The signal is reset to its default disposition, re-raised at this process,
// and given a moment to arrive. Where the re-raise cannot be delivered — on
// Windows, where signal-to-self is unsupported — the conventional
// 128-plus-signal-number exit is the fallback, so the process never hangs.
func dieFromSignal(sig os.Signal) {
	signal.Reset(sig)
	if p, err := os.FindProcess(os.Getpid()); err == nil {
		if err := p.Signal(sig); err == nil {
			time.Sleep(forceQuitGrace)
		}
	}
	os.Exit(exitCodeForSignal(sig))
}

// exitCodeForSignal maps a signal to the conventional 128-plus-signal-number
// exit code — 130 for SIGINT, 143 for SIGTERM — falling back to an interrupt's
// 130 for a signal carrying no numeric value on this platform.
func exitCodeForSignal(sig os.Signal) int {
	if s, ok := sig.(syscall.Signal); ok {
		return 128 + int(s)
	}
	return 128 + int(syscall.SIGINT)
}

// reportError renders err according to the error contract and returns the exit
// code the process should use. It is the single place that decides what a
// failure looks like on the terminal.
//
// root is the command tree's root and executed is the deepest command cobra
// matched; the two differ exactly when a subcommand's own validator failed,
// which is when the subcommand's usage — not the root's — is the useful one.
func reportError(out io.Writer, root, executed *cobra.Command, err error) int {
	var printed *cli.AlreadyPrintedError

	switch {
	case errors.As(err, &printed):
		// The command already wrote a friendly explanation. Printing anything
		// here would restate it in a less useful form.
	case isUnknownCommandOrFlagError(err):
		writeUsageAndError(out, root, err)
	case isPositionalArgError(err):
		writeUsageAndError(out, executed, err)
	default:
		fmt.Fprintln(out, err)
	}

	return exitFailure
}

// isUnknownCommandOrFlagError reports whether err is cobra's complaint about a
// verb or flag it does not recognise, which is a usage problem rather than a
// runtime one.
func isUnknownCommandOrFlagError(err error) bool {
	msg := err.Error()
	return strings.Contains(msg, "unknown command") || strings.Contains(msg, "unknown flag")
}

// isPositionalArgError reports whether err looks like a cobra positional-
// argument validator failure. Cobra's stock validators — ExactArgs, NoArgs,
// MinimumNArgs, MaximumNArgs, RangeArgs — all surface messages containing
// "arg(s)", and that substring appears in none of cobra's other error paths nor
// in harnaas's own errors, so it is a stable discriminator that does not reach
// into cobra internals.
func isPositionalArgError(err error) bool {
	return strings.Contains(err.Error(), "arg(s)")
}

// writeUsageAndError prints the command's usage before the error, so the reader
// sees what was expected and only then what went wrong.
func writeUsageAndError(out io.Writer, cmd *cobra.Command, err error) {
	if cmd == nil {
		fmt.Fprintln(out, err)
		return
	}
	fmt.Fprint(out, cmd.UsageString())
	fmt.Fprintf(out, "\nError: invalid usage: %v\n", err)
}

